SELECT stddev(icustays.los) AS standard_deviation FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 48 AND admissions.admission_type = 'H' AND icustays.los IS NOT NULL AND EXTRACT(YEAR FROM icustays.intime) BETWEEN 2015 AND 2016 AND EXTRACT(YEAR FROM icustays.outtime) BETWEEN 2015 AND 2016 AND (SELECT COUNT(*) FROM diagnoses_icd WHERE subject_id = patients.subject_id AND icd_code = '887.9') > 0;